#include <bits/stdc++.h>
using namespace std;

// Days since 1970-01-01 for a proleptic Gregorian date (Howard Hinnant's algorithm).
long long daysFromCivil(long long y, long long m, long long d) {
    y -= m <= 2;
    long long era = (y >= 0 ? y : y - 399) / 400;
    long long yoe = y - era * 400;
    long long doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    long long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

void civilFromDays(long long z, int &y, int &m, int &d) {
    z += 719468;
    long long era = (z >= 0 ? z : z - 146096) / 146097;
    long long doe = z - era * 146097;
    long long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    long long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    long long mp = (5 * doy + 2) / 153;
    d = doy - (153 * mp + 2) / 5 + 1;
    m = mp < 10 ? mp + 3 : mp - 9;
    y = yoe + era * 400 + (m <= 2);
}

int clockMinutes(const string &t) { int h, mi; sscanf(t.c_str(), "%d:%d", &h, &mi); return h * 60 + mi; }

// Absolute minutes since the epoch for "YYYY-MM-DD HH:MM".
long long parseStamp(const string &s) {
    int y, mo, d, h, mi;
    sscanf(s.c_str(), "%d-%d-%d %d:%d", &y, &mo, &d, &h, &mi);
    return daysFromCivil(y, mo, d) * 1440 + h * 60 + mi;
}

string format(long long minutes) {
    long long day = minutes / 1440, rest = minutes % 1440;
    int y, m, d;
    civilFromDays(day, y, m, d);
    char buf[32];
    snprintf(buf, sizeof buf, "%04d-%02d-%02d %02lld:%02lld", y, m, d, rest / 60, rest % 60);
    return buf;
}

int main() {
    string a, b;
    getline(cin, a);
    getline(cin, b);
    long long start = parseStamp(a), end = parseStamp(b);
    int w;
    cin >> w;
    vector<vector<pair<int, int>>> windows(7);
    for (int i = 0; i < w; i++) {
        int wd;
        string s, e;
        cin >> wd >> s >> e;
        windows[wd].push_back({clockMinutes(s), clockMinutes(e)});
    }
    vector<long long> found;
    for (long long day = start / 1440; day <= end / 1440; day++) {
        int weekday = ((day + 3) % 7 + 7) % 7; // 1970-01-01 was a Thursday; Monday = 0
        for (auto [s, e] : windows[weekday]) {
            long long base = day * 1440 + s, finish = day * 1440 + e;
            // Slot grid starts at the period's own start.
            for (long long cur = base; cur + 30 <= finish; cur += 30)
                if (cur >= start && cur + 30 <= end) found.push_back(cur);
        }
    }
    sort(found.begin(), found.end());
    found.erase(unique(found.begin(), found.end()), found.end());
    string out = to_string(found.size()) + "\n";
    for (long long c : found) out += format(c) + "," + format(c + 30) + "\n";
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

public class Main {
    static int clockMinutes(String t) {
        String[] p = t.split(":");
        return Integer.parseInt(p[0]) * 60 + Integer.parseInt(p[1]);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        DateTimeFormatter fmt = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
        LocalDateTime start = LocalDateTime.parse(br.readLine().trim(), fmt);
        LocalDateTime end = LocalDateTime.parse(br.readLine().trim(), fmt);
        int w = Integer.parseInt(br.readLine().trim());
        List<List<int[]>> windows = new ArrayList<>();
        for (int i = 0; i < 7; i++) windows.add(new ArrayList<>());
        for (int i = 0; i < w; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int wd = Integer.parseInt(st.nextToken());
            windows.get(wd).add(new int[]{clockMinutes(st.nextToken()), clockMinutes(st.nextToken())});
        }
        // Work in absolute minutes from the start date's midnight.
        LocalDate first = start.toLocalDate();
        long startMin = Duration.between(first.atStartOfDay(), start).toMinutes();
        long endMin = Duration.between(first.atStartOfDay(), end).toMinutes();
        TreeSet<Long> found = new TreeSet<>();
        long days = end.toLocalDate().toEpochDay() - first.toEpochDay();
        for (long d = 0; d <= days; d++) {
            int weekday = first.plusDays(d).getDayOfWeek().getValue() - 1; // Monday = 0
            for (int[] win : windows.get(weekday)) {
                long base = d * 1440 + win[0], finish = d * 1440 + win[1];
                // Slot grid starts at the period's own start.
                for (long cur = base; cur + 30 <= finish; cur += 30)
                    if (cur >= startMin && cur + 30 <= endMin) found.add(cur);
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(found.size()).append('\n');
        LocalDateTime origin = first.atStartOfDay();
        for (long c : found)
            sb.append(origin.plusMinutes(c).format(fmt)).append(',').append(origin.plusMinutes(c + 30).format(fmt)).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

const layout = "2006-01-02 15:04"

func clockMinutes(t string) int {
	p := strings.Split(t, ":")
	h, _ := strconv.Atoi(p[0])
	m, _ := strconv.Atoi(p[1])
	return h*60 + m
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	start, _ := time.Parse(layout, strings.TrimSpace(sc.Text()))
	sc.Scan()
	end, _ := time.Parse(layout, strings.TrimSpace(sc.Text()))
	sc.Scan()
	w, _ := strconv.Atoi(strings.TrimSpace(sc.Text()))
	windows := make([][][2]int, 7)
	for i := 0; i < w && sc.Scan(); i++ {
		f := strings.Fields(sc.Text())
		wd, _ := strconv.Atoi(f[0])
		windows[wd] = append(windows[wd], [2]int{clockMinutes(f[1]), clockMinutes(f[2])})
	}
	// Work in absolute minutes from the start date's midnight (UTC, no DST).
	origin := time.Date(start.Year(), start.Month(), start.Day(), 0, 0, 0, 0, time.UTC)
	startMin := int(start.Sub(origin).Minutes())
	endMin := int(end.Sub(origin).Minutes())
	lastDay := time.Date(end.Year(), end.Month(), end.Day(), 0, 0, 0, 0, time.UTC)
	days := int(lastDay.Sub(origin).Hours() / 24)
	seen := map[int]bool{}
	var found []int
	for d := 0; d <= days; d++ {
		weekday := (int(origin.AddDate(0, 0, d).Weekday()) + 6) % 7 // Monday = 0
		for _, win := range windows[weekday] {
			base, finish := d*1440+win[0], d*1440+win[1]
			// Slot grid starts at the period's own start.
			for cur := base; cur+30 <= finish; cur += 30 {
				if cur >= startMin && cur+30 <= endMin && !seen[cur] {
					seen[cur] = true
					found = append(found, cur)
				}
			}
		}
	}
	sort.Ints(found)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, len(found))
	for _, c := range found {
		a := origin.Add(time.Duration(c) * time.Minute).Format(layout)
		b := origin.Add(time.Duration(c+30) * time.Minute).Format(layout)
		fmt.Fprintln(out, a+","+b)
	}
}
